const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kyiv = ee.Geometry.Polygon([
    [30.2, 50.6],
    [30.8, 50.6],
    [30.8, 50.3],
    [30.2, 50.3],
    [30.2, 50.6]
  ]);

  const jan2022 = ['2022-01-01', '2022-01-31'];
  const mar2022 = ['2022-03-01', '2022-03-31'];

  // 2. Data Acquisition - VIIRS Nighttime Lights
  const viirsJan = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(jan2022[0], jan2022[1])
    .filterBounds(kyiv);

  const viirsMar = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(mar2022[0], mar2022[1])
    .filterBounds(kyiv);

  // Check collection sizes
  const janSize = viirsJan.size().getInfo();
  const marSize = viirsMar.size().getInfo();

  console.log(`January 2022 Images: ${janSize}`);
  console.log(`March 2022 Images: ${marSize}`);

  if (janSize === 0 || marSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get mean composites
  const janMean = viirsJan.mean();
  const marMean = viirsMar.mean();

  // 3. Processing - Calculate mean radiance
  const janRadiance = janMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kyiv,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const marRadiance = marMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kyiv,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  // Check for valid pixels
  const janCount = janMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: kyiv,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const marCount = marMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: kyiv,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`January Radiance: ${janRadiance?.toFixed(4)}, Pixels: ${janCount}`);
  console.log(`March Radiance: ${marRadiance?.toFixed(4)}, Pixels: ${marCount}`);

  // 4. Validation & Final Answer
  if (janRadiance === null || marRadiance === null || 
      isNaN(janRadiance) || isNaN(marRadiance) ||
      janCount === 0 || marCount === 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if March radiance is less than January radiance
  if (marRadiance < janRadiance) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
